int cdrom_select_disc(struct cdrom_device_info *cdi, unsigned long arg)
{
    if (!cdi || !cdi->ops || !cdi->ops->select_disc) {
        return -ENOSYS;
    }

    if (arg >= CDROM_MAX_DISCS) {
        return -EINVAL;
    }

    if (cdi->ops->select_disc(cdi, arg) < 0) {
        return -EIO;
    }

    return 0;
}

int cdrom_select_disc(struct cdrom_device_info *cdi, unsigned long arg)
{
    if (!cdi->ops->select_disc) {
        return -EINVAL;
    }

    if (arg > CDROM_DISC_MAX) {
        return -EINVAL;
    }

    if (cdi->disc_selection_func) {
        return cdi->disc_selection_func(cdi, arg);
    } else {
        return generic_cdrom_select_disc(cdi, arg);
    }

    return 0;
}

int cdrom_select_disc(struct cdrom_device_info *cdi, unsigned long arg)
{
    if (!cdi->capability & CDC_SELECT_DISC)
        return -ENOSYS;

    if (arg >= cdi->n_discs)
        return -EINVAL;

    if (cdi->ops->select_disc)
        return cdi->ops->select_disc(cdi, arg);

    return -ENOSYS;
}

int cdrom_select_disc(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!cdi || arg >= CDROM_MAX_DISC) {
        return -EINVAL;
    }

    if (cdi->select_disc) {
        return cdi->select_disc(cdi, arg);
    }

    return generic_select_disc(cdi, arg);
}

